// CSD_RATIONALE_BEGIN
// Built from attempt 2 (best at 40.8%) with three targeted improvements:
//
// 1. MODE-G FIX: After the main loop exits, if no `<<` span was ever opened in
//    `generated` (mode_G: 5-7 examples that produce no delimiters), force-open a
//    constrained span and run CloseSpanWithinBudget on the remaining budget to
//    generate + close the final answer expression.
//
// 2. HIGHER REPETITION PENALTY (8.0 vs 4.0): The `!!!!` repetition loops occur
//    because SafeRepetitionPenaltyStep applies a FLAT 4.0 penalty once per unique
//    token, regardless of how many times it appears in `generated`. If the LM's
//    logit gap for `!` over the next parser-valid token exceeds 4.0 in comparison
//    contexts (e.g. after `==`), the penalty never breaks the loop. Doubling to 8.0
//    aggressively breaks the loop at the cost of slight variable-name logit reduction,
//    which is preferable to infinite `!` repetition losing the span budget.
//
// 3. GUIDANCE: Explicit prohibition of comparison operators (==, !=, >, <) inside
//    << >> spans reduces the frequency of comparison-context entry that initiates
//    the `!` loop. Also emphasises `<<>>` format requirement to reduce mode-G.
//
// Core mechanics (unchanged from attempt 2):
//   - Outside spans: UnconstrainedStep until `<<` detected by RenderedEndsWith
//   - Inside spans (budget > closeReserve=80): SafeRepetitionPenaltyStep(8.0)
//   - Budget guard (remaining <= 80): CloseSpanWithinBudget for dead-end-aware close
//   - Final cleanup: CloseSpanWithinBudget on any remaining open span
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 — parser_validity:
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
//   (CloseSpanWithinBudget, remaining <= closeReserve):
//     Postcondition guarantees insideOut ==> parser.IsValidPrefix(currentOut).
//     Both closed (insideOut=false, implication vacuous) and still-open paths
//     preserve the invariant. ✓
//
//   (outside span branch, RenderedEndsWith triggers):
//     Sets currentConstrainedOut := [], which satisfies IsValidPrefix([]) by
//     the method precondition parser.IsValidPrefix([]). Otherwise insideConstrainedOut
//     stays false (implication vacuous). ✓
//
//   (IsCompletePrefix branch — CloseConstrainedSpan):
//     Sets insideConstrainedOut := false; implication vacuously true. ✓
//
//   (constrained step, non-EOS — SafeRepetitionPenaltyStep + AppendConstrainedToken):
//     SafeRepetitionPenaltyStep hard-masks to parser-valid tokens plus EOS, so
//     next is EOS or parser-valid. AppendConstrainedToken postcondition asserts
//     parser.IsValidPrefix(currentOut). ✓
//
//   (constrained step EOS): break without state change; invariant held on entry. ✓
//
//   (mode-G fix — OpenConstrainedSpan sets currentConstrainedOut := []):
//     IsValidPrefix([]) holds by method precondition. ✓
//
//   (final cleanup — CloseSpanWithinBudget): same postcondition argument as above. ✓
//
// Invariant 2 — progress: |generated| <= |generatedPrefix| + steps
//
//   (CloseSpanWithinBudget, s = steps_before, remaining = maxSteps - s):
//     |cg| <= |generated| + remaining <= |generatedPrefix| + s + (maxSteps-s)
//           = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: |generated| <= |generatedPrefix| + steps. ✓
//
//   (outside branch): steps += 1; at most one token appended to generated. ✓
//   (IsCompletePrefix): steps += 1; CloseConstrainedSpan appends at most `>>`. ✓
//   (constrained step non-EOS): steps += 1; AppendConstrainedToken appends one token. ✓
//   (constrained step EOS): steps += 1; generated unchanged; bound preserved. ✓
//
//   (mode-G fix — OpenConstrainedSpan appends exactly `<<`, steps += 1):
//     |fg| = |generated| + 1 <= |generatedPrefix| + old_steps + 1
//           = |generatedPrefix| + steps. ✓
//
//   (final cleanup after mode-G fix, remaining = maxSteps - steps_after_fix):
//     |cg| <= |fg| + remaining <= |generatedPrefix| + steps_after_fix + (maxSteps - steps_after_fix)
//           = |generatedPrefix| + maxSteps.
//     After steps := maxSteps: bound holds. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm,
  "Solve the problem step by step. " +
  "You MUST wrap every intermediate symbolic expression in << >> delimiters as you work. " +
  "End your answer with: The final answer is <<symbolic expression>>. " +
  "Inside << >> use ONLY: numbers, variable names from the problem, +, -, *, /, //, %, **, (), int(). " +
  "NEVER write comparison operators (==, !=, >, <, >=, <=) inside << >>. " +
  "NEVER write assignments (=) or if/else inside << >>. " +
  "Use // for integer (floor) division and int() to cast to integer. " +
  "Use ** for exponentiation. " +
  "Use parentheses to make operator precedence explicit.");

var closeReserve: nat := 80;
var steps: nat := 0;

while steps < maxSteps
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var remaining: nat := maxSteps - steps;

  if insideConstrainedOut && remaining <= closeReserve {
    // Budget running low inside a span: dead-end-aware forced close
    var cg, ci, cc := helpers.CloseSpanWithinBudget(
      lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := maxSteps;
    break;
  } else if !insideConstrainedOut {
    var next := helpers.UnconstrainedStep(lm, prompt, generated);
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      generated := generated + [next];
      if RenderedEndsWith(generated, "<<") {
        insideConstrainedOut := true;
        currentConstrainedOut := [];
      }
    }
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    var cg, ci, cc := helpers.CloseConstrainedSpan(
      lm, parser, generated, currentConstrainedOut
    );
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
  } else {
    // Constrained generation: higher penalty (8.0) aggressively breaks ! repetition loops
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := helpers.SafeRepetitionPenaltyStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, generated, 8.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Mode-G fix: if the model never opened any << span, force-open one for the final answer
if !insideConstrainedOut && steps < maxSteps {
  var genStr := CSDHelpers.PrefixToString(generated);
  var numSpans := CSDHelpers.CountSubstring(genStr, "<<");
  if numSpans == 0 {
    var fg, fi, fc := helpers.OpenConstrainedSpan(lm, generated);
    generated := fg;
    insideConstrainedOut := fi;
    currentConstrainedOut := fc;
    steps := steps + 1;
  }
}

// Final cleanup: close any remaining open span with whatever budget is left
if insideConstrainedOut && steps < maxSteps {
  var remaining: nat := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, remaining
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

